import{_ as i,o as e,c as t,a5 as a}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Trạng thái triển khai Admin Management — 2026-10-02","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/implementation-status-2026-10-02.md","filePath":"feature/admin-management/implementation-status-2026-10-02.md"}'),o={name:"feature/admin-management/implementation-status-2026-10-02.md"};function h(c,n,r,s,d,l){return e(),t("div",null,[...n[0]||(n[0]=[a('<h1 id="trang-thai-trien-khai-admin-management-—-2026-10-02" tabindex="-1">Trạng thái triển khai Admin Management — 2026-10-02 <a class="header-anchor" href="#trang-thai-trien-khai-admin-management-—-2026-10-02" aria-label="Permalink to &quot;Trạng thái triển khai Admin Management — 2026-10-02&quot;">​</a></h1><h2 id="đa-trien-khai-va-kiem-chung" tabindex="-1">Đã triển khai và kiểm chứng <a class="header-anchor" href="#đa-trien-khai-va-kiem-chung" aria-label="Permalink to &quot;Đã triển khai và kiểm chứng&quot;">​</a></h2><p>Giai đoạn nền tảng cho FR3.10.5/6/9 theo <a href="./plan.html">plan</a>:</p><ul><li>Tab user từ API thật, DTO không chứa passwordHash/otpCode/totpSecret; tìm tên/email, lọc system role/trạng thái và phân trang.</li><li>Strike YELLOW/ORANGE/RED, quy đổi đúng nhóm ba Vàng và liên kết nguồn, không dùng lại nguồn, gỡ nguồn không cascade sang Cam.</li><li>Vi phạm mới reset hạn của thẻ đang hiệu lực, không hồi sinh thẻ đã hết/gỡ; xử lý cả biên thời gian trước khi worker chạy.</li><li>Ba Cam hoặc Đỏ tạo review chờ; xác nhận có checkbox/lý do mới khóa30 ngày. Không tự phạt/ADMIN ngang hàng; không đổi quyền sở hữu hay đình chỉ Agency.</li><li>Mở tự động khi đủ hạn, giữ generation phiên cũ vô hiệu, transactional email outbox có retry. Test SMTP dùng mock, không gửi email thử tới người dùng thật.</li><li>UI Việt/Anh, light/dark, 390px/1440px; giữ bằng chứng khi mutation thất bại và retry cùng operationId.</li><li>Đã backup database dev ở <code>F:/LEARN/DA/.tmp/brandhub-before-admin-20261002.dump</code>, áp dụng migration cộng thêm. Không thay dữ liệu SUSPENDED/DELETED cũ thành ACTIVE.</li></ul><h2 id="bang-chung" tabindex="-1">Bằng chứng <a class="header-anchor" href="#bang-chung" aria-label="Permalink to &quot;Bằng chứng&quot;">​</a></h2><ul><li>Lần kiểm chứng cuối:67/67 test liên quan pass, gồm auth/login/refresh/OAuth/2FA, security, strike/lifecycle và PostgreSQL integration. Log <code>.tmp/admin-verified-tests.log</code>.</li><li>Unit RED→GREEN: StrikePolicy (4 test), AdminAccountService, AccountAccessPolicy, lifecycle; thêm regression cho expired flag, session generation và stale User save sau sanction.</li><li><code>AdminAccountDatabaseTest</code>: PostgreSQL17 thật, migration lặp an toàn; quy đổi/pardon/DTO/idempotency; xác nhận/mở lại/email retry; sáu writer đồng thời; stale profile/login save bị optimistic lock từ chối. Database test riêng <code>brandhub_admin_20261001_test</code>, không xử phạt user dev thật.</li><li><code>AdminSecurityTest</code>:401/403, role ADMIN cũ không vượt quyền hiện tại, DEACTIVATED, blacklist, refresh token không dùng như access, UUID/status không hợp lệ400.</li><li><code>JwtSessionVersionTest</code>: ký và parse RSA thật cho session generation trên cả access và refresh.</li><li>Playwright <code>tests/e2e/admin/accounts.spec.ts</code>:6/6 pass, API response được mock cho kiểm tra UI. Đã xem4 ảnh VI/EN/light/dark.</li><li><code>npm run build</code> và ESLint các file đổi: pass.</li><li>Smoke HTTP thật qua Gateway: login dev Admin thành công, profile roleADMIN, GET admin/users thành công, không có trường bí mật; không token→401. Business8081, Gateway8080 và web3000 đã khởi động trong phiên làm việc.</li></ul><h2 id="loi-baseline-khong-che-giau" tabindex="-1">Lỗi baseline, không che giấu <a class="header-anchor" href="#loi-baseline-khong-che-giau" aria-label="Permalink to &quot;Lỗi baseline, không che giấu&quot;">​</a></h2><h3 id="bo-sung-sua-loi-đang-nhap-—-2026-10-02" tabindex="-1">Bổ sung sửa lỗi đăng nhập — 2026-10-02 <a class="header-anchor" href="#bo-sung-sua-loi-đang-nhap-—-2026-10-02" aria-label="Permalink to &quot;Bổ sung sửa lỗi đăng nhập — 2026-10-02&quot;">​</a></h3><p>Đã sửa stale bearer chặn login/Dev Quick Login: web bỏ Authorization ở các POST tự xác thực; backend chỉ bỏ lọc access token cho đúng tám endpoint, vẫn kiểm tra credentials và bảo vệ API cần đăng nhập. Chi tiết và bằng chứng ở <a href="./../authentication/3-2-2-sign-in-with-email/test.html#bằng-chứng-regression--2026-10-02">FR3.2.2 test</a>:94 auth/security test và8 UI test pass; hai luồng đăng nhập thật vào Admin thành công sau restart Business. Không thay quy tắc sanction/session revocation.</p><h3 id="baseline-toan-bo-business-suite" tabindex="-1">Baseline toàn bộ Business suite <a class="header-anchor" href="#baseline-toan-bo-business-suite" aria-label="Permalink to &quot;Baseline toàn bộ Business suite&quot;">​</a></h3><p>Full Business suite sau thay đổi:278 test,1 failure,10 errors,9 skipped. Cùng11 lỗi đã có trước khi viết code (baseline243 test,1 failure,10 errors,9 skipped):</p><ul><li><code>WorkspaceServiceTest.listMyWorkspaces_returnsWorkspacesForActiveMemberships</code> thất bại.</li><li>Ba test <code>WorkspaceServiceTest.createWorkspace_*</code> lỗi do fixture không đáp ứng quyền Agency Owner.</li><li>Bảy test <code>WorkspaceControllerIntegrationTest</code> không khởi tạo được context vì thiếu mock <code>ClientProfileRepository</code> của <code>RequireRoleAspect</code>.</li></ul><p>Log: <code>.tmp/admin-baseline-tests.log</code>, <code>.tmp/admin-final-backend.log</code>, <code>.tmp/admin-verified-tests.log</code>, <code>.tmp/admin-web-qa.log</code>, <code>.tmp/admin-verified-web-build.log</code> trong workspace. Lần chạy khi Docker tắt có4 lỗi kết nối bổ sung; đã bật Docker và chạy lại,4 lỗi đó không còn.</p><h2 id="review" tabindex="-1">Review <a class="header-anchor" href="#review" aria-label="Permalink to &quot;Review&quot;">​</a></h2><p>Review độc lập phát hiện hai race ở login/refresh và một lỗi expired-flag. Đã thêm optimistic row version, session generation và reconcile trước vi phạm mới; lần review lại không còn finding quan trọng trong ba điểm này.</p><h2 id="dashboard-tong-quan-—-cap-nhat-2026-10-02" tabindex="-1">Dashboard Tổng quan — cập nhật 2026-10-02 <a class="header-anchor" href="#dashboard-tong-quan-—-cap-nhat-2026-10-02" aria-label="Permalink to &quot;Dashboard Tổng quan — cập nhật 2026-10-02&quot;">​</a></h2><ul><li><code>/admin</code> mở Tổng quan; <code>/admin?view=users</code> mở danh sách. Sidebar và menu điện thoại dành riêng Admin, không yêu cầu chọn Agency; link Monitoring giữ chức năng hiện có.</li><li>4 KPI thật, biểu đồ đăng ký 7/30/90 ngày, múi giờ VN/UTC, phân bố trạng thái, strike còn hiệu lực/review chờ và user mới. API <code>GET /api/v1/admin/statistics</code> chỉ dành cho Admin, snapshot PostgreSQL nhất quán; không lấy dữ liệu mock từ màn Admin cũ.</li><li>Danh sách có avatar, toolbar, nhãn thẻ; bộ lọc theo URL và drill-down; giữ luồng phạt hiện có. VI/EN, light/dark, desktop/mobile; trạng thái lỗi/retry/forbidden có kiểm chứng.</li><li>13 backend test và 18 UI test pass; ESLint/build pass. Browser thật đã đăng nhập, đổi múi giờ, mở danh sách/dialog thành công. Chi tiết: <a href="./3-10-2-platform-statistics-overview/test.html">FR3.10.2 test</a>. Ảnh <code>.tmp/admin-dashboard-live-vi.png</code> trong workspace.</li></ul><h2 id="phan-con-lai" tabindex="-1">Phần còn lại <a class="header-anchor" href="#phan-con-lai" aria-label="Permalink to &quot;Phần còn lại&quot;">​</a></h2><p>Không coi10 FR đã xong. FR3.10.7/8 (provisioning/activation/profile/paid next-cycle plan), FR3.10.4 (moderation và publisher), FR3.10.1 (broadcast email), FR3.10.11/12 (revenue/PDF) chưa triển khai đầy đủ. FR3.10.2 đã có dashboard foundation ở trên, còn rankingAgency, tài chính, custom range, cache vàPDF. Các mục chưa triển khai trong Admin mới hiển thị chưa sẵn sàng, không giả lập thao tác thành công. Metadata subscription của danh sách user vẫn còn ở giai đoạn2.</p><p>FLAGGED hiện được lưu và cho đăng nhập; yêu cầu ADMIN duyệt/giữ lịch bài tại luồng publish phải được nối ở giai đoạn3 trước khi nghiệm thu toàn bộ FR3.10.5/9. Email outbox hiện chỉ phục vụ mở khóa, không thay thế broadcast của FR3.10.1. Monitoring của Tuấn không sửa.</p><p>Chưa commit/push. Giữ nguyên các thay đổi auth/dev-login/AI có sẵn trong working tree trước phiên này.</p><h2 id="doanh-thu-thong-bao-email-pdf-—-cap-nhat-2026-10-04" tabindex="-1">Doanh thu, thông báo email, PDF — cập nhật 2026-10-04 <a class="header-anchor" href="#doanh-thu-thong-bao-email-pdf-—-cap-nhat-2026-10-04" aria-label="Permalink to &quot;Doanh thu, thông báo email, PDF — cập nhật 2026-10-04&quot;">​</a></h2><ul><li>FR 3.10.11: <code>GET /api/v1/admin/revenue?from&amp;to&amp;timezone&amp;plan</code> trên bảng <code>transactions</code> PayOS hiện có; MRR/ARR, tiền thu gộp/hoàn/ròng, tách tiền tệ, MRR theo gói, giao dịch gần nhất; màn <code>/admin?view=revenue</code>.</li><li>FR 3.10.1: <code>/api/v1/admin/notifications</code> (tạo, sửa, hủy, lịch sử, ước tính, catalog gói); worker xác định người nhận lúc gửi, giao qua <code>admin_email_outbox</code>; màn <code>/admin?view=email</code>.</li><li>FR 3.10.12: <code>POST /api/v1/admin/reports</code> (REVENUE/USER/PLATFORM) + tải bằng token 24 giờ; trang <code>/admin?view=reports</code> và nút xuất ở Doanh thu/Người dùng.</li><li>Migration <a href="./../../database/migrations/2026-10-04-admin-notifications-reports.sql.html">2026-10-04-admin-notifications-reports.sql</a>; dependency <code>openpdf</code> + <code>openpdf-fonts-extra</code> 2.0.3.</li><li>Dữ liệu demo: profile <code>seed-admin-demo</code> (<code>AdminDemoSeeder</code>), xem README seed.</li><li>Chi tiết kiểm chứng và giới hạn: test.md của <a href="./3-10-1-push-notification/test.html">3.10.1</a>, <a href="./3-10-11-view-revenue-dasboard/test.html">3.10.11</a>, <a href="./3-10-12-export-report-file-pdf/test.html">3.10.12</a>.</li><li>Chưa làm: FR 3.10.4 Kiểm duyệt (thiếu nguồn vi phạm FR 3.6.33/34 và nối publisher), FR 3.10.7/8. Hai init SQL chưa gộp migration strikes 2026-10-01 và migration 2026-10-04.</li></ul><h2 id="kiem-duyet-noi-dung-—-cap-nhat-2026-10-04" tabindex="-1">Kiểm duyệt nội dung — cập nhật 2026-10-04 <a class="header-anchor" href="#kiem-duyet-noi-dung-—-cap-nhat-2026-10-04" aria-label="Permalink to &quot;Kiểm duyệt nội dung — cập nhật 2026-10-04&quot;">​</a></h2><ul><li>FR 3.10.4: PostgreSQL <code>content_moderation_reviews</code> (quyết định, thẻ phạt, audit) + Mongo <code>post_versions</code> (snapshot bất biến) + <code>posts.content_version</code>.</li><li>Hook gửi duyệt trong <code>PostServiceImpl</code> (code của Lộc, người dùng đã đồng ý); API nội bộ cho Tuấn/Phước; màn <code>/admin?view=moderation</code>.</li><li>Dev Business dùng Mongo local (<code>MONGODB_URI</code> trong <code>.env</code>, không commit), không ghi vào Atlas chung. Test dùng DB riêng <code>brandhub_moderation_test</code>.</li><li>Hai init SQL (<code>docs/database/</code> và <code>scripts/</code>) đã gộp migration strikes 2026-10-01, notifications/reports và moderation 2026-10-04; dựng DB trắng từ mỗi file thành công.</li><li>Chi tiết: <a href="./3-10-4-content-moderation-queue/test.html">3.10.4 test</a>.</li></ul><h2 id="thong-bao-trong-app-—-cap-nhat-2026-10-04" tabindex="-1">Thông báo trong app — cập nhật 2026-10-04 <a class="header-anchor" href="#thong-bao-trong-app-—-cap-nhat-2026-10-04" aria-label="Permalink to &quot;Thông báo trong app — cập nhật 2026-10-04&quot;">​</a></h2><ul><li>Theo quyết định mới của người dùng, FR 3.10.1 gửi cả email và in-app. Chi tiết: <a href="./confirmed-decisions-2026-10-01.html">quyết định</a>, <a href="./3-10-1-push-notification/test.html">test</a>.</li><li>Sự cố đã xử lý: broadcast thử &quot;test thử thôi&quot; tới Tất cả người dùng có 5 địa chỉ seed mang domain thật; đã hoãn rồi đánh dấu <code>DEV_RECIPIENT_BLOCKED</code> trước khi SMTP gửi. Không có email nào tới người ngoài.</li><li>Sidebar Admin dùng logo BrandHub thật (<code>BrandHubLogo</code>).</li></ul><h2 id="tao-va-sua-nguoi-dung-—-cap-nhat-2026-10-04" tabindex="-1">Tạo và sửa người dùng — cập nhật 2026-10-04 <a class="header-anchor" href="#tao-va-sua-nguoi-dung-—-cap-nhat-2026-10-04" aria-label="Permalink to &quot;Tạo và sửa người dùng — cập nhật 2026-10-04&quot;">​</a></h2><ul><li>FR 3.10.7: <code>POST /api/v1/admin/users</code> tạo tài khoản <code>PENDING_VERIFICATION</code>, email kích hoạt bắt buộc (link 1 lần, 72h), trang <code>/activate-account</code> để người dùng tự đặt mật khẩu.</li><li>FR 3.10.8: <code>GET/PATCH /api/v1/admin/users/{id}</code>; email bất biến, bảo vệ vai trò, đổi gói áp dụng kỳ sau và vẫn cần thanh toán.</li><li>Migration <code>2026-10-05-admin-user-provisioning.sql</code>: chạy 2 lần DB test, backup, 2 lần DB dev; đã gộp vào 2 init SQL, dựng DB trắng từ mỗi file thành công.</li><li>Chi tiết: <a href="./3-10-7-create-user/test.html">3.10.7 test</a>, <a href="./3-10-8-update-user/test.html">3.10.8 test</a>.</li></ul>',29)])])}const m=i(o,[["render",h]]);export{u as __pageData,m as default};
